/* Climate City data integration for the adapted Curevo template. */
(()=>{'use strict';
const toggle=document.getElementById('mobileToggle'),menu=document.getElementById('mobileMenu');
function closeMenu(){menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation')}
toggle.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){closeMenu();toggle.focus()}});document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!toggle.contains(e.target))closeMenu()});
const categories={museum:'Culture & heritage',hospital:'Healthcare & wellbeing',schools:'Education & learning',sports:'Sport & active living',market:'Enterprise & local life',diplomatic:'International exchange',wildlife:'Nature & conservation',hotel:'Hospitality',landscape:'Landscape & gardens',waterfront:'Waterfront leisure',station:'Proposed mobility',homes:'Homes & neighbourhoods',energy:'Clean energy',food:'Food & agriculture'};
fetch('data.json').then(r=>{if(!r.ok)throw Error('Destination data unavailable');return r.json()}).then(data=>{const ds=data.destinations||[];const byId=Object.fromEntries(ds.map(d=>[d.id,d]));document.querySelectorAll('[data-image]').forEach(img=>{const[id,n]=img.dataset.image.split(':');const d=byId[id],v=d?.images?.[Number(n)]||d?.images?.[0];if(v){img.src=typeof v==='string'?v:v.src;img.alt=typeof v==='string'?d.title:v.title||d.title}});const cards=document.getElementById('destinationCards');for(const id of ['hotel','schools','market','diplomatic','sports','wildlife']){const d=byId[id];if(!d)continue;const a=document.createElement('a');a.className='destination-card';a.href='explore.html#'+id;const visual=document.createElement('div');visual.className='destination-card-image';const img=document.createElement('img');img.src=d.images?.[0]?.src||data.masterplan||'assets/masterplan.jpg';img.alt=d.images?.[0]?.title||d.title;img.loading='lazy';const arrow=document.createElement('span');arrow.className='card-arrow';arrow.textContent='';visual.append(img,arrow);const meta=document.createElement('div');meta.className='destination-card-meta';const copy=document.createElement('div');const h=document.createElement('h3');h.textContent=d.title;const p=document.createElement('p');p.textContent=categories[id]||d.eyebrow||'';copy.append(h,p);const count=document.createElement('span');count.textContent=(d.images?.length||1)+' images · Open gallery';meta.append(copy,count);a.append(visual,meta);cards.append(a)}const places=document.getElementById('allPlaces');if(places)ds.forEach((d,i)=>{const a=document.createElement('a');a.className='place-link';a.href='explore.html#'+d.id;const num=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');const name=document.createElement('span');name.textContent=d.title;const arrow=document.createElement('b');arrow.textContent='';a.append(num,name,arrow);places.append(a)})}).catch(()=>{const p=document.createElement('p');p.textContent='Explore all destinations in the interactive masterplan.';const a=document.createElement('a');a.href='explore.html';a.className='pill-button';a.textContent='Open the masterplan ';document.getElementById('destinationCards').append(p,a)});
})();

(()=>{
const film=document.getElementById('cityFilm'),playback=document.getElementById('filmPlayback'),error=document.getElementById('filmError');
if(!film||!playback)return;
playback.addEventListener('click',()=>{film.controls=true;film.play().catch(()=>{error.hidden=false;playback.hidden=false})});
film.addEventListener('play',()=>{playback.hidden=true;error.hidden=true});
film.addEventListener('pause',()=>{playback.hidden=false});
film.addEventListener('ended',()=>{playback.hidden=false;film.controls=false});
film.addEventListener('error',()=>{error.hidden=false;playback.hidden=false});
})();
window.addEventListener('message',e=>{const f=document.querySelector('.explorer-frame');if(e.origin!==location.origin||e.source!==f?.contentWindow)return;if(e.data?.type==='climate-scroll'){const delta=Number(e.data.delta);if(Number.isFinite(delta))window.scrollBy(0,Math.max(-500,Math.min(500,delta)))}if(e.data?.type==='climate-journey')document.body.classList.toggle('in-city-journey',!!e.data.open)});

(()=>{const film=document.getElementById('heroFilm'),button=document.getElementById('heroPlayback');if(!film)return;film.muted=true;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;if(reduced){film.autoplay=false;film.pause()}else film.play().catch(()=>{});function sync(){button.textContent=film.paused?'Play':'Pause';button.setAttribute('aria-label',film.paused?'Play hero video':'Pause hero video')}button.onclick=()=>{if(film.paused)film.play().catch(sync);else film.pause()};film.addEventListener('play',sync);film.addEventListener('pause',sync);sync()})();
